// Generate mock "career page" job listings for each tracked company.
// Each company produces one item so downstream nodes process them independently
// (via Split In Batches behaviour, since Code node returning multiple items
// automatically fans them out one-by-one to the next node).

const trackedCompanies = [
  { name: 'Google', domain: 'google.com' },
  { name: 'Microsoft', domain: 'microsoft.com' },
  { name: 'Amazon', domain: 'amazon.com' },
  { name: 'IBM', domain: 'ibm.com' },
  { name: 'Adobe', domain: 'adobe.com' }
];

const mockRolesByCompany = {
  'google.com': ['Software Engineer Intern', 'Cloud Solutions Architect'],
  'microsoft.com': ['Product Manager', 'Azure Support Engineer'],
  'amazon.com': ['Warehouse Operations Associate', 'SDE II'],
  'ibm.com': ['Consultant - AI Practice', 'Campus Hire - Data Engineer'],
  'adobe.com': ['UX Designer', 'Marketing Analyst Intern']
};

const hiringTypes = ['INTERN', 'FULL_TIME', 'CONTRACT', 'BULK_HIRING', 'CAMPUS_DRIVE'];

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(16);
}

const items = [];

for (const company of trackedCompanies) {
  const roles = mockRolesByCompany[company.domain];
  const roleTitle = roles[Math.floor(Math.random() * roles.length)];
  const hiringType = hiringTypes[Math.floor(Math.random() * hiringTypes.length)];
  const sourceUrl = `https://careers.${company.domain}/jobs/${simpleHash(roleTitle + company.domain)}`;
  const dedupeKey = simpleHash(`${company.domain}|${roleTitle}|${sourceUrl}`);

  items.push({
    json: {
      company: {
        name: company.name,
        domain: company.domain
      },
      source: 'career_page_watcher',
      source_url: sourceUrl,
      role_title: roleTitle,
      hiring_type: hiringType,
      dedupe_key: dedupeKey,
      detected_at: new Date().toISOString(),
      raw_payload: {
        note: 'Mock career-page listing for development/testing.',
        generated_by: 'n8n-career-page-watcher'
      }
    }
  });
}

return items;

const error = $json.error || 'Unknown error';
console.error('[Career Page Watcher] Failed to send signal to backend:', error);

return [{
  json: {
    status: 'FAILED',
    workflow: 'career-page-watcher',
    error,
    failed_at: new Date().toISOString()
  }
}];

return [{
  json: {
    status: 'SUCCESS',
    workflow: 'career-page-watcher',
    sent_at: new Date().toISOString(),
    response: $json
  }
}];
